function save(){if(window.__grandReset||tourMode)return;try{localStorage.setItem(SAVE_KEY,JSON.stringify(state));}catch{if(storageOK)toast('This browser could not save progress. Keep this tab open.');storageOK=false;}updateHud();}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3400);}
