 $('#mini-achievements').innerHTML=rows.map(a=>`<div class="mini-achievement"><div class="mini-achievement-icon">${icon(state.unlocked.includes(a.id)?'check':'star',17)}</div><div><strong>${esc(a.name)}</strong><p>${esc(a.desc)}</p></div><em>${Math.min(progress(a,state),a.target)}/${a.target}</em></div>`).join('');
 const residentsHere=npcs.filter(a=>!a.staff),around=residentsHere.length?residentsHere.slice(0,3):hotel.inRoom('lobby').slice(0,3);
 $('#guest-list').innerHTML=around.map(g=>`<button class="guest-row" data-action="guest" data-index="${g.id}"><div class="guest-portrait">${guestSvg(g)}</div><div><strong>${g.name}</strong><span>${esc(g.title)}</span><span>${ROOMS[g.room].short} · ${esc(hotel.describe(g))}</span></div><i></i></button>`).join('')+`<button class="text-button" style="margin-top:18px" data-action="people">Meet all 20 residents →</button>`;
